sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here

    var assetSysId = current.request_item.variables.asset_request;

    var gr = new GlideRecord('x_1583830_it_ass_0_asset_request');
    gr.addQuery('sys_id', assetSysId);
    gr.query();
    gr.setLimit(1);


    if (gr.next()) {
        gr.status = 'closed_incomplete';

        var assetId = gr.asset;

        var ga = new GlideRecord('cmdb_ci');
        ga.addQuery('sys_id', assetId);
        ga.setLimit(1);
        ga.query();

        if (ga.next()) {

            var grAlmHardware = new GlideRecord('alm_hardware');
            grAlmHardware.addQuery('ci.sys_id', 'STARTSWITH', assetId);
            grAlmHardware.setLimit(1);
            grAlmHardware.query();
            if (grAlmHardware.next()) {

                var hardware = grAlmHardware.sys_id;

                var grConsumables = new GlideRecord('alm_consumable');
                grConsumables.addQuery('parent.sys_id', hardware);
                grConsumables.setLimit(1);
                grConsumables.query();
                if (grConsumables.next()) {
                    var mod = grConsumables.model;
                    var model = new GlideRecord('cmdb_model');
                    model.addQuery('sys_id', mod);
                    model.setLimit(1);
                    model.query();
                    if (model.next()) {
                        grConsumables.deleteRecord();
                        model.deleteRecord();
                    }

                }
                grAlmHardware.deleteRecord;
            }

            ga.deleteRecord();

        }
        gr.update();
    }

})(current, previous);
